#include "cpu.hpp"
#include "jit.hpp"
#include <chrono>
#include <iostream>
int main(){
 pc::CPU c(65536);c.s[pc::CS].big=true;
 const uint8_t code[]={0x0f,0xab,0xc8,0x0f,0xba,0xf0,17,0x0f,0xbb,0xcb,0x0f,0xa3,0xc8,0x72,0,0x43,0x49,0x75,0xed};
 for(unsigned n=0;n<sizeof(code);++n)c.write(n,code[n],1);
 c.r[pc::CX]=5000000;c.r[pc::BX]=0x87654321;c.r[pc::AX]=0x12345678;
 pc::Jit jit(c,true,0);auto start=std::chrono::steady_clock::now();
 do{jit.run();}while(c.ip!=sizeof(code));
 auto ns=std::chrono::duration_cast<std::chrono::nanoseconds>(std::chrono::steady_clock::now()-start).count();
 std::cout<<"{\"ns\":"<<ns<<",\"instructions\":"<<c.instructions<<",\"native\":"<<jit.nativeInstructions<<",\"ax\":"<<c.r[pc::AX]<<",\"bx\":"<<c.r[pc::BX]<<",\"cx\":"<<c.r[pc::CX]<<",\"flags\":"<<c.flags<<"}\n";
}
